/**
 * O convite — a tela de compartilhar o próprio Papiro.
 *
 * Nasce da Fase 9: o dashboard precisava de um botão para passar o app adiante,
 * "semelhante ao cartão de contato, mas específico". A semelhança é a forma —
 * cartão centrado, QR grande, ações embaixo —, e a diferença é o assunto: aqui o
 * que se entrega não é uma pessoa, é o aplicativo.
 *
 * **O link é o endereço público do Papiro**, cravado em `ENDERECO_PUBLICO`. Já
 * foi o `location` da aba, e estava errado: o convite não fala de onde o app foi
 * aberto, e sim de onde quem o recebe vai instalá-lo. Num build local o
 * `location` é `papiro.local`, um endereço que só existe nesta máquina — o
 * convite viraria um link morto assim que saísse dela.
 *
 * O QR é gerado sob demanda pelo mesmo `qrcode-generator` do cartão de contato,
 * com import tardio: quem nunca abre o convite não baixa o gerador.
 */

import { papiro } from '@marinx/flavors';
import { html } from 'lit';
import { S } from '../strings.ts';
import { abrir } from './dialogo.ts';
import { notificar } from './notificar.ts';

/** O endereço público do Papiro no GitHub Pages — é ele que se compartilha. */
export const ENDERECO_PUBLICO = 'https://luizcmarin.github.io/papiro';

/** O texto do convite, usado no WhatsApp, no compartilhamento e na cópia. */
export function textoDoConvite(endereco = ENDERECO_PUBLICO): string {
  return `${S.convite.mensagem}\n\n${endereco}`;
}

/** `https://wa.me/?text=…` abre o WhatsApp já com a mensagem, sem destinatário. */
function linkWhatsApp(endereco: string): string {
  return `https://wa.me/?text=${encodeURIComponent(textoDoConvite(endereco))}`;
}

async function gerarQr(endereco: string): Promise<string> {
  const { default: qrcode } = await import('qrcode-generator');
  const qr = qrcode(0, 'M');
  qr.addData(endereco);
  qr.make();
  return qr.createDataURL(6, 8);
}

async function copiar(endereco: string): Promise<void> {
  try {
    await navigator.clipboard.writeText(textoDoConvite(endereco));
    notificar(S.convite.copiado);
  } catch {
    notificar(S.leitura.semCopiar, 'warning');
  }
}

async function compartilharConvite(endereco: string): Promise<void> {
  // `typeof`, e não `'share' in navigator`: o tipo do DOM declara `share` como
  // sempre presente, e o `in` estreitaria o ramo do fallback para `never`.
  if (typeof navigator.share !== 'function') {
    await copiar(endereco);
    return;
  }

  try {
    await navigator.share({
      title: papiro.displayName,
      text: S.convite.mensagem,
      url: endereco,
    });
  } catch {
    // Cancelar o compartilhamento não é erro: o usuário desistiu.
  }
}

/** Abre o convite. Resolve quando o diálogo termina de fechar. */
export function abrirConvite(): Promise<void> {
  const endereco = ENDERECO_PUBLICO;
  let qr = '';

  return abrir<void>(
    S.convite.titulo,
    undefined,
    (fechar, _dialogo, redesenhar) => {
      if (qr === '') {
        void gerarQr(endereco).then((dados) => {
          qr = dados;
          redesenhar();
        });
      }

      return html`
        <div class="convite">
          <img class="convite__logo" src="icons/papiro.svg" alt="" aria-hidden="true" />
          <h2 class="convite__nome">${papiro.displayName}</h2>
          <p class="convite__lema">${S.convite.lema}</p>

          ${
            qr === ''
              ? html`<div class="convite__qr convite__qr--vazio"><st-spinner></st-spinner></div>`
              : html`<img class="convite__qr" src=${qr} alt=${S.convite.qrAlt} />`
          }

          <p class="convite__dica">${S.convite.dica}</p>

          <div class="convite__acoes">
            <st-button variant="success" href=${linkWhatsApp(endereco)} target="_blank">
              <st-icon slot="prefix" name="brand-whatsapp"></st-icon>${S.convite.whatsapp}
            </st-button>
            <st-button variant="primary" @click=${() => void compartilharConvite(endereco)}>
              <st-icon slot="prefix" name="share"></st-icon>${S.convite.compartilhar}
            </st-button>
            <st-button @click=${() => void copiar(endereco)}>
              <st-icon slot="prefix" name="copy"></st-icon>${S.convite.copiar}
            </st-button>
          </div>

          <p class="convite__endereco">${endereco}</p>

          <st-button class="convite__fechar" @click=${() => fechar(undefined)}>
            ${S.acoes.fechar}
          </st-button>
        </div>
      `;
    },
    { semCabecalho: true, classe: 'dialogo-convite' },
  );
}
